WWP_SDTNotificationsDataSample {
WWP_SDTNotificationsDataSampleItem { &DateTime = now() NotificationIconClass = "fas fa-layer-group NotificationFontIconSuccess" NotificationTitle = "Group Records & Totalizers" NotificationDescription = "Group the records of a grid within a certain column and show totalizers of each group" NotificationDatetime = &DateTime }
WWP_SDTNotificationsDataSampleItem { NotificationIconClass = "fas fa-palette NotificationFontIconWarning" NotificationTitle = "Dark Designs" NotificationDescription = "Option to select dark designs in the Design System Wizard" &DateTime = &DateTime.AddHours(-2) NotificationDatetime = &DateTime }
WWP_SDTNotificationsDataSampleItem { NotificationIconClass = "fas fa-cog NotificationFontIconDanger" NotificationTitle = "100% Customizable" NotificationDescription = "Customize and create your own design system" &DateTime = &DateTime.AddHours(-5) NotificationDatetime = &DateTime }
WWP_SDTNotificationsDataSampleItem { NotificationIconClass = "far fa-star NotificationFontIconInfo" NotificationTitle = "Bookmarks" NotificationDescription = "Bookmark pages and have their shortcuts in the Master Page" &DateTime = &DateTime.AddHours(-8) NotificationDatetime = &DateTime }
WWP_SDTNotificationsDataSampleItem { NotificationIconClass = "fas fa-plus NotificationFontIconSuccess" NotificationTitle = "Add new" NotificationDescription = "Add new record of a DVelop Combo while editing other record" &DateTime = &DateTime.AddHours(-36) NotificationDatetime = &DateTime }
WWP_SDTNotificationsDataSampleItem { NotificationIconClass = "fas fa-caret-down NotificationFontIconInfoLight" NotificationTitle = "Expand record" NotificationDescription = "Expand record of a grid in order to visualize more information" &DateTime = &DateTime.AddHours(-65) NotificationDatetime = &DateTime } }
